/**
 * Singleflight: coalesces concurrent calls for the same key so that only one
 * underlying computation runs; all callers await the same in-flight promise.
 *
 * - Different keys proceed independently.
 * - A failed compute removes itself from the map, so the NEXT request starts
 *   fresh (failures are never cached / no poisoned entries).
 */
class SingleFlight {
  /**
   * @param {(key: string) => Promise<any>} fn async compute keyed by `key`
   */
  constructor(fn) {
    if (typeof fn !== 'function') throw new TypeError('fn must be a function');
    this.fn = fn;
    /** @type {Map<string, Promise<any>>} */
    this.inflight = new Map();
    /** per-key invocation counter (how many times fn actually ran) */
    this.invocations = new Map();
  }

  /**
   * Returns the in-flight promise for `key`, or starts a new computation.
   * All concurrent callers for the same key receive the SAME promise.
   */
  do(key) {
    const existing = this.inflight.get(key);
    if (existing) return existing;

    // Count an actual compute invocation for this key.
    this.invocations.set(key, (this.invocations.get(key) || 0) + 1);

    const p = (async () => this.fn(key))().finally(() => {
      // Detach regardless of outcome so failures don't poison later requests.
      if (this.inflight.get(key) === p) this.inflight.delete(key);
    });

    this.inflight.set(key, p);
    return p;
  }

  /** How many times the compute actually executed for `key` (or total). */
  count(key) {
    return key === undefined
      ? [...this.invocations.values()].reduce((a, b) => a + b, 0)
      : this.invocations.get(key) || 0;
  }

  /** Number of keys with a compute currently in flight. */
  get size() {
    return this.inflight.size;
  }
}

module.exports = { SingleFlight };
