const express = require('express');
const { SingleFlight } = require('./singleflight');

const COMPUTE_MS = 200;

/**
 * Simulated expensive compute (~200 ms). `failKeys` makes specific keys throw,
 * used by the failure test.
 */
function createApp({ failKeys = new Set() } = {}) {
  const app = express();

  let computeCalls = 0;
  const callsByKey = new Map();

  async function expensiveCompute(key) {
    computeCalls += 1;
    callsByKey.set(key, (callsByKey.get(key) || 0) + 1);
    await new Promise((r) => setTimeout(r, COMPUTE_MS));
    if (failKeys.has(key)) {
      throw new Error(`compute failed for ${key}`);
    }
    return { key, computedAtMs: COMPUTE_MS };
  }

  // One shared singleflight instance => concurrent same-key requests coalesce.
  const flight = new SingleFlight(expensiveCompute);

  app.get('/expensive/:key', async (req, res) => {
    try {
      const result = await flight.do(req.params.key);
      res.json(result);
    } catch (err) {
      // Any waiter whose compute failed gets a 502; the entry was already
      // evicted in the promise's finally-block, so the next request recomputes.
      res.status(502).json({ error: 'upstream compute failed' });
    }
  });

  // Introspection for tests/monitoring: how many real computes happened.
  app.get('/_stats', (_req, res) => {
    res.json({
      totalComputes: computeCalls,
      perKey: Object.fromEntries(callsByKey),
    });
  });

  return { app, stats: () => ({ totalComputes: computeCalls }) };
}

module.exports = { createApp, COMPUTE_MS };

if (require.main === module) {
  const port = process.env.PORT || 3000;
  const { app } = createApp();
  app.listen(port, () => console.log(`listening on :${port}`));
}
