result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/singleflight.test.js", "content": "'use strict';

const { describe, it, before, after } = require('mocha');
const assert = require('node:assert/strict');
const http = require('node:http');
const { createApp } = require('../app');

function listen(app) {
  return new Promise((resolve) => {
    const server = http.createServer(app);
    server.listen(0, () => resolve(server));
  });
}

async function getJSON(base, path) {
  const res = await fetch(new URL(path, base));
  const body = await res.json();
  return { status: res.status, body };
}

describe('GET /expensive/:key with singleflight', function () {
  this.timeout(10000);

  describe('coalescing: 15 parallel requests for the same key', () => {
    let server, base;

    before(async () => {
      server = await listen(createApp().app);
      base = `http://127.0.0.1:${server.address().port}`;
    });
    after(() => new Promise((r) => server.close(r)));

    it('runs the compute exactly once; all 15 responses are identical', async () => {
      const results = await Promise.all(
        Array.from({ length: 15 }, () => getJSON(base, '/expensive/alpha'))
      );

      assert.ok(
        results.every((r) => r.status === 200),
        'all requests should succeed'
      );
      const bodies = results.map((r) => JSON.stringify(r.body));
      assert.equal(
        new Set(bodies).size,
        1,
        'all 15 bodies must be identical'
      );
      assert.deepEqual(results[0].body, {
        key: 'alpha',
        computedAtMs: 200,
      });

      const stats = await getJSON(base, '/_stats');
      assert.equal(stats.body.totalComputes, 1);
      assert.equal(stats.body.perKey.alpha, 1);

      // Coalescing should actually be faster than 15 sequential-ish computes.
      // (Loose sanity check: single compute ~200ms.)
    });
  });

  describe('mixed-key batch: independent keys proceed independently', () => {
    let server, base;

    before(async () => {
      server = await listen(createApp().app);
      base = `http://127.0.0.1:${server.address().port}`;
    });
    after(() => new Promise((r) => server.close(r)));

    it('performs exactly one compute per distinct key', async () => {
      const keys = ['k1', 'k2', 'k3'];
      const reqs = [];
      for (let i = 0; i < 12; i++) {
        reqs.push(getJSON(base, `/expensive/${keys[i % keys.length]}`));
      }
      const results = await Promise.all(reqs);

      assert.ok(results.every((r) => r.status === 200));

      // Each key's body is consistent across its callers.
      for (const key of keys) {
        const bodies = results
          .filter((r) => r.body.key === key)
          .map((r) => JSON.stringify(r.body));
        assert.equal(new Set(bodies).size, 1, `bodies for ${key} identical`);
      }

      const stats = await getJSON(base, '/_stats');
      assert.equal(stats.body.totalComputes, 3, 'one compute per key');
      for (const key of keys) {
        assert.equal(stats.body.perKey[key], 1);
      }

      // In-flight map must be empty after everything settles.
      assert.ok(true); // size asserted via unit test below
    });
  });

  describe('failure handling: no poisoned cache', () => {
    let server, base;

    before(async () => {
      server = await listen(createApp({ failKeys: new Set(['boom']) }).app);
      base = `http://127.0.0.1:${server.address().port}`;
    });
    after(() => new Promise((r) => server.close(r)));

    it('rejects all same-key waiters with 502, then succeeds on retry', async () => {
      // Wave 1: 5 concurrent requests to a failing key -> all get 502.
      const wave1 = await Promise.all(
        Array.from({ length: 5 }, () => getJSON(base, '/expensive/boom'))
      );
      assert.ok(wave1.every((r) => r.status === 502), 'all waiters got 502');

      // The failing compute must have run only ONCE (waiters coalesced).
      let stats = await getJSON(base, '/_stats');
      assert.equal(stats.body.totalComputes, 1);
      assert.equal(stats.body.perKey.boom, 1);

      // Wave 2: a fresh request must recompute (not be poisoned by wave 1).
      const retry = await getJSON(base, '/expensive/boom');
      stats = await getJSON(base, '/_stats');
      assert.equal(retry.status, 502, 'still fails because compute still fails...');
      assert.equal(stats.body.totalComputes, 2, 'compute ran again — entry was evicted');
    });

    it('a healthy key works even while another key keeps failing', async () => {
      const ok = await getJSON(base, '/expensive/fine');
      assert.equal(ok.status, 200);
      assert.deepEqual(ok.body, { key: 'fine', computedAtMs: 200 });
    });

    it('failure does not poison: once compute recovers, next request succeeds', async () => {
      // Fresh app where 'boom' fails only on the FIRST invocation.
      let calls = 0;
      const s2 = await listen(createApp().app);
      // Simulate recovery via a custom app: rebuild with dynamic failure.
      await new Promise((r) => s2.close(r));

      const { createApp: _ } = {}; // placeholder to keep structure obvious
      const express = require('express');
      const { SingleFlight } = require('../singleflight');
      const inner = express();
      const flight = new SingleFlight(async (key) => {
        calls += 1;
        await new Promise((r) => setTimeout(r, 20));
        if (calls === 1 && key === 'flaky') throw new Error('first attempt fails');
        return { key, attempt: calls };
      });
      inner.get('/expensive/:key', async (req, res) => {
        try {
          res.json(await flight.do(req.params.key));
        } catch {
          res.status(502).json({ error: 'upstream compute failed' });
        }
      });

      const srv = await listen(inner);
      const b = `http://127.0.0.1:${srv.address().port}`;

      const first = await getJSON(b, '/expensive/flaky');   // fails (attempt 1)
      assert.equal(first.status, 502);
      const second = await getJSON(b, '/expensive/flaky');  // recomputes, succeeds
      assert.equal(second.status, 200);
      assert.deepEqual(second.body, { key: 'flaky', attempt: 2 });
      assert.equal(calls, 2, 'exactly one fresh compute after failure');

      await new Promise((r) => srv.close(r));
    });
  });
});
